// GitHub Actions(slash-fix.yml)가 계산한 X-Hub-Signature-256을 검증한다.
// rawBody 옵션으로 받은 원본 바이트로 HMAC을 계산해야 GitHub이 보낸 서명과 정확히 일치한다
// (파싱 후 재직렬화된 JSON은 바이트가 달라져 서명이 깨질 수 있음).
// $binary 필드 위치는 n8n 버전에 따라 다를 수 있으니 설치된 버전으로 재확인할 것.
const crypto = require('crypto');
const secret = $env.GITHUB_WEBHOOK_SECRET;

const item = $input.first();
const rawBuffer = Buffer.from(item.binary.data.data, 'base64');
const rawBody = rawBuffer.toString('utf8');
const signatureHeader = (item.json.headers && item.json.headers['x-hub-signature-256']) || '';

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');

const sigBuf = Buffer.from(signatureHeader);
const expBuf = Buffer.from(expected);
const valid = sigBuf.length === expBuf.length && crypto.timingSafeEqual(sigBuf, expBuf);

if (!valid) {
  // 서명 불일치 - 흐름을 중단한다 (빈 배열을 반환하면 이후 노드가 실행되지 않음)
  return [];
}

return [{ json: JSON.parse(rawBody) }];

const body = $input.first().json;
const comment = body.comment;
const repo = body.repository;

const commentBody = (comment.body || '').trim();
let command = null;

if (commentBody === '/fix-build') command = 'fix-build';
else if (commentBody === '/fix-lint') command = 'fix-lint';
else if (commentBody === '/fix' && comment.in_reply_to_id) command = 'fix';

if (!command) return [];

let prNumber, prTitle, prUrl, headBranch, headSha;

if (body.pull_request) {
  // pull_request_review_comment 이벤트
  const pr = body.pull_request;
  prNumber = pr.number;
  prTitle = pr.title;
  prUrl = pr.html_url;
  headBranch = pr.head.ref;
  headSha = pr.head.sha;
} else if (body.issue && body.issue.pull_request) {
  // issue_comment 이벤트 (일반 PR 코멘트)
  prNumber = body.issue.number;
  prTitle = body.issue.title;
  prUrl = body.issue.html_url;

  // headBranch/headSha는 API로 조회 (whitelist-guard에서 보호 브랜치 여부를 판단하는 데 필요)
  const token = $env.GITHUB_TOKEN;
  const prData = await new Promise((resolve, reject) => {
    const https = require('https');
    const req = https.request({
      hostname: 'api.github.com',
      path: `/repos/${repo.owner.login}/${repo.name}/pulls/${prNumber}`,
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
        'User-Agent': 'n8n-jump-section'
      }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        if (res.statusCode >= 400) { reject(new Error(`HTTP ${res.statusCode}: ${data}`)); return; }
        try { resolve(JSON.parse(data)); } catch (e) { reject(new Error('Invalid JSON: ' + data.slice(0, 200))); }
      });
    });
    req.setTimeout(15000, () => { req.destroy(); reject(new Error('Request timeout')); });
    req.on('error', reject);
    req.end();
  });

  headBranch = prData.head.ref;
  headSha = prData.head.sha;
} else {
  return [];
}

return [{
  json: {
    command,
    prNumber,
    prTitle,
    prUrl,
    headBranch,
    headSha,
    repoOwner: repo.owner.login,
    repoName: repo.name,
    commentId: comment.id,
    filePath: comment.path || null,
    inReplyToId: comment.in_reply_to_id || null
  }
}];

// Generic V2 서명: HMAC-SHA256("<timestamp>.<body>"), X-Webhook-Signature-V2 + X-Webhook-Timestamp 헤더
// (Hermes 공식 문서 권장 방식 - 300초 이내 타임스탬프만 허용해 재전송 공격을 막는다)
const crypto = require('crypto');
const secret = $env.HERMES_WEBHOOK_SECRET;
const ctx = $input.first().json;

// 화이트리스트된 필드만 명시적으로 구성해 보낸다 (원본 GitHub 이벤트를 통째로 전달하지 않음)
const payload = {
  correlation_id: `cf-${ctx.repoName}-${ctx.prNumber}-${ctx.commentId}-${Date.now()}`,
  command: ctx.command,
  repo: { owner: ctx.repoOwner, name: ctx.repoName },
  pr: { number: ctx.prNumber, title: ctx.prTitle, url: ctx.prUrl },
  branch: { head_ref: ctx.headBranch, head_sha: ctx.headSha },
  comment: { id: ctx.commentId, path: ctx.filePath, in_reply_to_id: ctx.inReplyToId },
  callback: { url: $env.HERMES_CALLBACK_URL }
};

const body = JSON.stringify(payload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');

return [{
  json: {
    url: `${$env.HERMES_BASE_URL}/webhooks/${ctx.command}`,
    timestamp,
    signature,
    body
  }
}];
